Scanner sc = new Scanner(System.in);
int n = sc.nextInt(), count = 0, sum = 0, max = Integer.MIN_VALUE;
while (n != -1) {
  count++; sum += n;
  if (n > max) max = n;
  n = sc.nextInt();
}
System.out.println(count + " " + sum + " " + max);
for (int r = 1; r <= 4; r++) {
  for (int c = 1; c <= r; c++) System.out.print("#");
  System.out.println();
}
